import { Materia } from './materia.model';

export class PlanEstudio {
  private codigo: string;
  private anioVigencia: number;
  private materias: Materia[];

  constructor(codigo: string, anioVigencia: number, materias: Materia[]) {
    this.codigo = codigo;
    this.anioVigencia = anioVigencia;
    this.materias = materias;
  }

  getCodigo(): string { return this.codigo; }
  getAnioVigencia(): number { return this.anioVigencia; }

  getMaterias(): Materia[] {
    return this.materias;
  }

  getCorrelativasDe(materia: Materia): Materia[] {
    return materia.getCorrelativas();
  }
}
